CHRONICLE_PREFIX = "projects/fleet-sre-demo/locations/us/instances/mock-soar"

# Fleet integration topology, mirroring fixtures/fleet.yaml (protected):
# service -> integration and connector/job keys. D6/D7 should source this
# from the fleet config or the API instead of duplicating it here.
_SERVICE_TOPOLOGY: dict[str, dict[str, str]] = {
    "alert-ingestion": {
        "integration": "MockSentinel",
        "connector": "mock-sentinel-incidents",
    },
    "intel-sync": {
        "integration": "MockThreatIntel",
        "job": "sync-indicators",
    },
}


def full_resource_name(
    deployment: Deployment, component_id: str, kind: str
) -> str | None:
    """Full Chronicle name for a deployment component, or None when unknown.

    Connector/job instance IDs come from Deployment.resources; the
    integration instance ID is the environment (fixtures/fleet.yaml).
    """
    topo = _SERVICE_TOPOLOGY.get(deployment.service)
    if topo is None:
        return None
    integration = topo["integration"]
    if component_id == "integrationInstance":
        return (
            f"{CHRONICLE_PREFIX}/integrations/{integration}/"
            f"integrationInstances/{deployment.environment}"
        )
    instance = deployment.resources.get(component_id)
    if instance is None:
        return None
    if kind == "connectorInstance" and "connector" in topo:
        return (
            f"{CHRONICLE_PREFIX}/integrations/{integration}/connectors/"
            f"{topo['connector']}/connectorInstances/{instance}"
        )
    if kind == "jobInstance" and "job" in topo:
        return (
            f"{CHRONICLE_PREFIX}/integrations/{integration}/jobs/"
            f"{topo['job']}/jobInstances/{instance}"
        )
    return None


class Registry:
    """Contracts + deployments + scorecards with log routing (spec.md §4.1)."""

    def __init__(
        self,
        contracts: list["Contract"],
        deployments: list[Deployment],
        scorecards: dict[str, Any] | None = None,
    ) -> None:
        self._contracts = {c.service: c for c in contracts}
        self._deployments = {d.id: d for d in deployments}
        self._by_service: dict[str, list[Deployment]] = {}
        for dep in deployments:
            self._by_service.setdefault(dep.service, []).append(dep)
        self._scorecards = dict(scorecards) if scorecards else {}

    def contract(self, service: str) -> "Contract":
        return self._contracts[service]

    def deployments(self, service: str) -> list[Deployment]:
        return list(self._by_service.get(service, []))

    def deployment(self, id: str) -> Deployment:
        return self._deployments[id]

    def scorecard(self, service: str) -> Any:
        return self._scorecards.get(service)

    def route(self, entry: LogEntry) -> list[tuple[str, str]]:
        """Route an entry to [(deployment ID, component ID)].

        Uses the evaluator's routing (deliverables.md §D4 item 5):
        the component's container_name and match labels, then
        deploymentBy; a connector label maps through
        Deployment.resources, with jsonPayload.environment as fallback.
        """
        found: list[tuple[str, str]] = []
        container = entry.resource.labels.get("container_name")
        for service, contract in self._contracts.items():
            for component in contract.components:
                if component.logs.container_name != container:
                    continue
                if any(
                    key not in entry.labels
                    for key in component.logs.match
                ):
                    continue
                dep_id = self._resolve(
                    service, component.id, component.logs.deploymentBy,
                    entry,
                )
                if dep_id is not None:
                    found.append((dep_id, component.id))
        return found

    def _resolve(
        self, service: str, component_id: str, deployment_by: str,
        entry: LogEntry,
    ) -> str | None:
        if deployment_by.startswith("labels."):
            value = entry.labels.get(deployment_by[len("labels."):])
            if value is not None:
                for dep in self._by_service.get(service, []):
                    if dep.resources.get(component_id) == value:
                        return dep.id
            return self._env_fallback(service, entry)
        if deployment_by.startswith("jsonPayload."):
            node: Any = entry.jsonPayload
            for part in deployment_by.split(".")[1:]:
                if isinstance(node, dict) and part in node:
                    node = node[part]
                else:
                    return None
            if not isinstance(node, str):
                return None
            dep_id = f"{service}/{node}"
            return dep_id if dep_id in self._deployments else None
        return None

    def _env_fallback(self, service: str, entry: LogEntry) -> str | None:
        env = entry.jsonPayload.get("environment")
        if not isinstance(env, str):
            return None
        dep_id = f"{service}/{env}"
        return dep_id if dep_id in self._deployments else None"}

{"content":""""Chronicle HTTP client over httpx (dev auth header; ID tokens in D7)."""

from typing import Any

import httpx

from fleetsre.ports import ChronicleError


class ChronicleHttpClient:
    """ChronicleClient over HTTP with X-Fleetsre-Identity (mocks.md §4.2)."""

    def __init__(self, http: httpx.Client, identity: str) -> None:
        self._http = http
        self._identity = identity

    @property
    def identity(self) -> str:
        return self._identity

    def _headers(self) -> dict[str, str]:
        return {"X-Fleetsre-Identity": self._identity}

    def _raise(self, response: Any) -> None:
        try:
            parsed = response.json()
        except ValueError:
            parsed = {"message": response.text}
        body = parsed.get("error", parsed) if isinstance(parsed, dict) else {
            "message": str(parsed)
        }
        if not isinstance(body, dict):
            body = {"message": str(body)}
        raise ChronicleError(response.status_code, body)

    def _get(self, url: str, params: dict[str, Any] | None = None) -> Any:
        response = self._http.get(url, params=params, headers=self._headers())
        if response.status_code >= 400:
            self._raise(response)
        return response.json()

    def _post(self, url: str, body: Any) -> Any:
        response = self._http.post(url, json=body, headers=self._headers())
        if response.status_code >= 400:
            self._raise(response)
        return response.json()

    def get(self, name: str) -> dict[str, Any]:
        return self._get(f"/v1/{name}")

    def list_connector_logs(
        self, name: str, page_size: int
    ) -> dict[str, Any]:
        return self._get(f"/v1/{name}/logs", {"pageSize": page_size})

    def list_job_logs(self, name: str, page_size: int) -> dict[str, Any]:
        return self._get(f"/v1/{name}/logs", {"pageSize": page_size})

    def execute_test(self, name: str) -> dict[str, Any]:
        return self._post(f"/v1/{name}:executeTest", {})

    def patch(
        self, name: str, body: dict[str, Any], update_mask: list[str]
    ) -> dict[str, Any]:
        response = self._http.patch(
            f"/v1/{name}",
            params={"updateMask": ",".join(update_mask)},
            json=body,
            headers=self._headers(),
        )
        if response.status_code >= 400:
            self._raise(response)
        return response.json()

    def run_on_demand(
        self, name: str, body: dict[str, Any]
    ) -> dict[str, Any]:
        return self._post(f"/v1/{name}:runOnDemand", body)

    def set_logs_collection(
        self, name: str, enabled: bool
    ) -> dict[str, Any]:
        return self._post(f"/v1/{name}:setLogsCollection", {"enabled": enabled})
